def feature(text: str) -> float:
    "Entropy of the character distribution in the text"
    from collections import Counter
    import math
    char_count = Counter(text)
    total_chars = sum(char_count.values())
    return -sum((count / total_chars) * math.log(count / total_chars, 2) for count in char_count.values() if count > 0)

def feature(text: str) -> float:
    "Ratio of specific keywords related to the context"
    keywords = ['AYilunGOT', 'GOATYilun', 'YilunGOAT', 'ZZZZZZZZZZ']
    keyword_count = sum(1 for keyword in keywords if keyword in text)
    return float(keyword_count)
def feature(text: str) -> float:
    "Count of specific phrase occurrences in the text"
    phrase = 'YilunGOAT'
    count = text.count(phrase)
    return float(count)
def feature(text: str) -> float:
    'Entropy of character distribution in the text'
    from collections import Counter
    import math
    if len(text) == 0:
        return 0.0
    char_counts = Counter(text)
    probabilities = [count / len(text) for count in char_counts.values()]
    entropy = -sum(p * math.log2(p) for p in probabilities)
    return entropy

def feature(text: str) -> float:
    'Proportion of specific repeating characters in the text'
    total_length = len(text)
    if total_length == 0:
        return 0.0
    count_repeating = text.count('Z')
    return count_repeating / total_length

def feature(text: str) -> float:
    "Ratio of the most frequent character to the total number of characters"
    total_chars = len(text)
    if total_chars == 0:
        return 0.0
    char_counts = {}
    for char in text:
        if char.isalnum():
            char_counts[char] = char_counts.get(char, 0) + 1
    most_frequent = max(char_counts.values(), default=0)
    return most_frequent / total_chars

def feature(text: str) -> float:
    'Count of specific substrings (e.g., "GOATYilun") in the text'
    keyword = 'GOATYilun'
    return float(text.count(keyword))

def feature(text: str) -> float:
    "Number of distinct characters in the text"
    distinct_chars = set(text)
    return float(len(distinct_chars))
